/// <summary>
/// desigend from AVA
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable,SalesLine))]
internal final class AVASalesTableFrm_SalesLineDS_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <returns>true</returns>
int  active()
{
    int ret = next active();

    this.object(fieldNum(SalesLine,LinePercent)).allowEdit(true);
    this.object(fieldNum(SalesLine, SalesUnit)).allowEdit(NoYes::No);
    this.object(fieldNum(SalesLine, SalesUnit)).skip(NoYes::Yes);

    element.avaSalesLineTexteEditable();

    return ret;
}

/// <summary>
///     AVA <c>validateDelete</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
boolean validateDelete()
{
    boolean     retVal;
    SalesLine   locSalesLine;

    retVal = next validateDelete();

    if(retVal)
    {
        locSalesLine = element.SalesLine;
        if(locSalesLine.SalesStatus == SalesStatus::Invoiced)
        {
            retVal = checkFailed(strFmt("@SYS113823", locSalesLine.LineNum, locSalesLine.SalesId));
        }
    }

    return retVal;
}
